# Lennard-Jones pair energy, LNS CORDIC add/sub (generated by gen_lj.py: N=27, REPEATS=4)
# Final energy (one pass) in l10 (la0) and, converted, in f11.
# L registers: ls0 = 1.0, ls1 = 4.0, ls2-ls4 = xi yi zi, lt0-lt2 = xj yj zj,
#              lt3-lt6 = temporaries, la0 = E.
.data
pos: .float 1.0042, 1.0345, 1.00755
     .float 1.00955, 1.00875, 2.1483
     .float 1.0189, 1.04275, 3.19015
     .float 1.01495, 2.07235, 0.95775
     .float 0.9989, 2.15145, 2.10975
     .float 0.961, 2.08595, 3.2162
     .float 1.00945, 3.20965, 0.9518
     .float 1.0345, 3.271, 2.1041
     .float 0.98275, 3.23505, 3.26665
     .float 2.14925, 0.9822, 1.03405
     .float 2.1427, 1.02455, 2.12615
     .float 2.07135, 1.0302, 3.2806
     .float 2.08945, 2.12665, 1.0487
     .float 2.16025, 2.1081, 2.13405
     .float 2.12335, 2.10465, 3.2876
     .float 2.089, 3.2778, 1.03415
     .float 2.0757, 3.26015, 2.14785
     .float 2.09295, 3.26355, 3.26185
     .float 3.1906, 0.9834, 1.01955
     .float 3.27875, 0.97855, 2.09825
     .float 3.24405, 0.98795, 3.25575
     .float 3.19835, 2.09655, 1.0073
     .float 3.22015, 2.1659, 2.14955
     .float 3.20785, 2.15195, 3.21645
     .float 3.21555, 3.2848, 1.01365
     .float 3.22115, 3.23125, 2.13425
     .float 3.1976, 3.2052, 3.25095
lone: .word 0          # LNS +1.0 (raw word 0x00000000)
lbuf: .zero 324
.text
    la s0, pos
    la s3, lbuf
    li s1, 27                  # N
    li s2, 4                  # REPEATS
# convert every coordinate once: lbuf[k] = fcvt.lns.s(pos[k])
    li t0, 81                  # 3N words
    mv t3, s0
    mv t4, s3
cvt_loop:
    flw f0, 0(t3)
    fcvt.lns.s lt0, f0
    lsw lt0, 0(t4)
    addi t3, t3, 4
    addi t4, t4, 4
    addi t0, t0, -1
    bnez t0, cvt_loop
    la t0, lone
    llw ls0, 0(t0)             # 1.0
    li t0, 0x40800000
    fmv.w.x f0, t0
    fcvt.lns.s ls1, f0         # 4.0
rep_loop:
    laddc la0, lzero, lzero     # E = 0
    li t1, 0                   # i
    mv t3, s3                  # &lbuf[i]
i_loop:
    llw ls2, 0(t3)
    llw ls3, 4(t3)
    llw ls4, 8(t3)
    addi t2, t1, 1             # j = i + 1
    addi t4, t3, 12            # &lbuf[j]
    bge t2, s1, i_next
j_loop:
    llw lt0, 0(t4)
    llw lt1, 4(t4)
    llw lt2, 8(t4)
    lsubc lt0, ls2, lt0         # dx
    lsubc lt1, ls3, lt1         # dy
    lsubc lt2, ls4, lt2         # dz
    lmul  lt3, lt0, lt0
    lmul  lt4, lt1, lt1
    laddc lt3, lt3, lt4
    lmul  lt4, lt2, lt2
    laddc lt3, lt3, lt4         # r2
    ldiv  lt4, ls0, lt3         # inv = 1 / r2
    lmul  lt5, lt4, lt4
    lmul  lt5, lt5, lt4         # s6
    lmul  lt6, lt5, lt5         # s12
    lsubc lt6, lt6, lt5         # s12 - s6
    lmul  lt6, ls1, lt6         # v = 4 * (s12 - s6)
    laddc la0, la0, lt6         # E += v
    addi t2, t2, 1
    addi t4, t4, 12
    blt t2, s1, j_loop
i_next:
    addi t1, t1, 1
    addi t3, t3, 12
    blt t1, s1, i_loop
    addi s2, s2, -1
    bnez s2, rep_loop
    fcvt.s.lns f11, la0
    li a0, 0
    li a7, 10                  # exit
    ecall
